export const ManufacturingSiteRegionKeyToLabel = {
  'Americas': 'Americas',
  'Europe': 'Europe',
  'AsiaPacific': 'Asia Pacific'
} as const;
export type ManufacturingSiteRegionKey = keyof typeof ManufacturingSiteRegionKeyToLabel;

export interface ManufacturingSite {
  /**
   * @displayName Manufacturing Site ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Site Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  siteName: string;
  /**
   * @displayName Briefing Sequence
   * @validationRule Required for create/update operations
   */
  briefingSequence: number;
  /**
   * @displayName Country
   * @validationRule Required for create/update operations
   */
  country: string;
  /**
   * @displayName Region
   * @validationRule Required for create/update operations
   */
  regionKey: ManufacturingSiteRegionKey;
  /**
   * @displayName Site Code
   * @validationRule Required for create/update operations
   */
  siteCode: string;
}

export const _ManufacturingSite = 'ManufacturingSite' as const;